import { createTheme } from '@mui/material/styles';

const theme = createTheme({
  typography: {
    fontFamily: 'Prompt, sans-serif',
  },
  palette: {
    primary: {
      main: '#1ab5caff', // เขียวมิ้นต์
    },
    secondary: {
      main: '#1b413cff', // สีทองอ่อน (ดาว)
    },
    info:{
      main:'#ffffffff'
    },
    error:{
      main: '#cf3e3eff'
    },
    success:{
      main:'#159e75ff'
    },
    warning:{
      main:'#c0bd1aff'
    },
    background: {
      default: 'linear-gradient(135deg, #1ab5caff 0%, #44bbcaff 50%, #20aabdff 100%)',
    },
  },
  components: {
    MuiCard: {
      styleOverrides: {
        root: {
          borderRadius: 0, // ไม่มีมุมโค้ง
        },
      },
    },
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: 0,
          textTransform: 'none',
          fontWeight: 600,
        },
      },
    },
  },
});

export default theme;
